// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "", ""); }
    function testFuzz_property(uint256 amount, address caller) public {
        vm.assume(caller != address(0));
        vm.prank(address(this));
        c.mintToken(caller, amount);
        uint256 supplyBefore = c.totalSupply();
        vm.prank(caller);
        try c.burn(amount) { } catch { }
        uint256 supplyAfter = c.totalSupply();
        if (caller == c.owner()) {
            assertTrue(supplyAfter <= supplyBefore, "owner burn must not increase supply");
        } else {
            assertTrue(supplyAfter == supplyBefore, "non-owner cannot change totalSupply via burn");
        }
    }
}
